using UnityEngine;using System;using System.Reflection;using System.Collections.Generic;
public static class VerifyShovelLoads {
 public static object Run(){var source=UnityEngine.Object.FindFirstObjectByType<HeldGrainToolLevels>(FindObjectsInactive.Include);var copy=UnityEngine.Object.Instantiate(source.gameObject,source.transform.parent);var flags=BindingFlags.NonPublic|BindingFlags.Instance;try{var levels=copy.GetComponent<HeldGrainToolLevels>();var tool=copy.GetComponent<ShovelTool>();typeof(ShovelTool).GetMethod("Awake",flags).Invoke(tool,null);var result=new List<string>();for(int i=1;i<=3;i++){for(int k=0;k<levels.levels.Length;k++)levels.levels[k].SetActive(k==i);typeof(HeldGrainToolLevels).GetField("selected",flags).SetValue(levels,i);var profile=levels.levels[i].GetComponent<HeldShovelPose>();tool.BindShovel(profile);var physics=profile.grainPhysics;typeof(ShovelGrainPhysics).GetMethod("Awake",flags).Invoke(physics,null);tool.Cargo.Clear();tool.Cargo.Add(GrainType.Corn,tool.CapacityKg);tool.Tick(.02f);for(int k=0;k<120;k++)typeof(ShovelGrainPhysics).GetMethod("Simulate",flags).Invoke(physics,new object[]{1f/60});if(physics.KernelCount<10)throw new Exception("Missing grain at "+i+": "+physics.KernelCount);typeof(ShovelGrainPhysics).GetMethod("LateUpdate",flags).Invoke(physics,null);tool.ComposePresentation(1,Vector2.zero,0,Vector3.zero,out var offset,out var rotation);if(Quaternion.Angle(rotation,Quaternion.identity)>.01f||offset.magnitude>.001f)throw new Exception("Idle pose changed");var expected=copy.transform.InverseTransformPoint(profile.gripAnchor.position);var cached=(Vector3)typeof(ShovelTool).GetField("gripInHands",flags).GetValue(tool);if(Vector3.Distance(expected,cached)>.0001f)throw new Exception("Wrong grip");typeof(ShovelTool).GetMethod("UpdateScoopPose",flags).Invoke(tool,new object[]{1f});if(Quaternion.Angle(tool.RotationOffset,Quaternion.identity)>.05f || tool.PositionOffset.magnitude>.001f)throw new Exception("Scoop did not return to rest");tool.CancelAction();result.Add("LVL_"+(i+1)+": "+physics.KernelCount+" kernels, "+physics.PackedKernelCount+" packed, own handle anchor, authored idle pose preserved");}return result;}finally{UnityEngine.Object.DestroyImmediate(copy);}}
}
